import React, { useContext } from "react";
import { AuthContext } from "../Context/AuthContext";

function Toolbar({ socket }) {
  const { user } = useContext(AuthContext);

  const clearBoard = () => {
    if (user.role === "admin") {
      socket.emit("clearBoard");
    }
  };

  return (
    <div className="flex p-2 bg-gray-200 border-b space-x-4">
      <button className="px-3 py-1 bg-blue-500 text-white rounded">Pen</button>
      <button className="px-3 py-1 bg-gray-500 text-white rounded">Eraser</button>
      <button className="px-3 py-1 bg-green-500 text-white rounded">Text</button>
      <button className="px-3 py-1 bg-purple-500 text-white rounded">Upload</button>
      {user.role === "admin" && (
        <button
          onClick={clearBoard}
          className="px-3 py-1 bg-red-500 text-white rounded"
        >
          Clear Board
        </button>
      )}
    </div>
  );
}

export default Toolbar;
